  await expect(members.setAbsence(t.actors.member, { ...input, delegateUserId: input.userId })).rejects.toThrow();
  await expect(members.setAbsence(t.actors.member, { ...input, endsAt: input.startsAt })).rejects.toThrow();
  const replacement = { ...input, delegateUserId: null, note: null };
